import { loadFont } from "@remotion/google-fonts/Poppins";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";
import { MAPA_V2 } from "./mapaV2";

// ATBYTE (cliente do Gustavo marketing). Motion vertical da Gestão TIC: monitorar antes que a tecnologia pare.
// Material: só o logo (src/foto-1.jpg) e o texto do cliente, gravado como veio (voz o locutor, src/voz-v1.mp3, 34,8 s;
// a 1ª frase foi regravada em src/voz-v1-frase1.mp3, 5,1 s, porque o "Uma" saiu engolido; o resto segue nos tempos do v1).
// Identidade: marinho e verde do logo, cinza-claro do nome; Poppins como no site. O símbolo de 8 peças é redesenhado em SVG
// para montar peça por peça; o nome "grupo atbyte" é o recorte do logo enviado. Servidor, rede e ícones são ilustrativos.
// Limpo: fundo liso, o texto entra e fica parado; o movimento contínuo fica nos objetos.
// Tempos = tempos da locução (t = 0 é o começo do mp3; o vídeo tem LEAD de entrada).

const { fontFamily: F } = loadFont("normal", { weights: ["300", "500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const ATB_FPS = 30;
const LEAD = 0.3;
export const ATB_FRAMES = Math.round((LEAD + 34.8 + 1.7) * ATB_FPS);
// v3 (voz-v2.mp3, 32,3 s, mais animada e com "Á Tê Báite"): o tempo novo vira o antigo pela tabela, palavra por palavra
export const ATB_V3_FRAMES = Math.round((LEAD + 32.3 + 1.7) * ATB_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const NAVY = "#011E56";
const NAVY_2 = "#0A2C6E";
const NAVY_3 = "#1B3F86";
const GREEN = "#1FB553";
const GREEN_L = "#5BD98A";
const LIGHT = "#ECEEED";
const PAPER = "#F4F6F9";
const RED = "#E5484D";
const SHADOW = "0 34px 80px rgba(1,30,86,0.18), 0 6px 16px rgba(1,30,86,0.10)";

// trocas de cena
const T2 = 5.55, T3 = 9.45, T4 = 14.25, T5 = 21.35, T6 = 29.6;

// texto: entra desfocado com leve escala e fica parado; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.4): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.18);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 16 + o * 12).toFixed(1)}px)`,
    transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})`,
  };
};

// linhas de título; a linha de destaque vem numa faixa de cor chapada
type L = [string, number, string?, number?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; hlColor?: string; weight?: number }> = ({ t, items, size, top, color = LIGHT, out, hlColor = "#FFFFFF", weight = 700 }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.14 }}>
    {items.map(([w, at, hl, sz], i) => {
      const s = sz ?? size;
      return (
        <div key={i} style={{ fontFamily: F, fontWeight: hl ? 800 : weight, fontSize: s, lineHeight: 1.12, letterSpacing: "-0.035em", whiteSpace: "nowrap", color: hl ? hlColor : color, ...(hl ? { background: hl, padding: `${s * 0.04}px ${s * 0.3}px ${s * 0.1}px`, borderRadius: s * 0.22 } : {}), ...blurIn(t, at, out) }}>
          {w}
        </div>
      );
    })}
  </div>
);

// ───────── símbolo: 8 peças em anel (cada uma um quadrado com um canto cortado) ─────────
const PIECE = "M-60,-200 L45,-200 L45,-92 L0,-92 L-60,-148 Z";
const Simbolo: React.FC<{ size: number; t: number; at: number; spin?: number; color?: string; gather?: number }> = ({ size, t, at, spin = 0, color = GREEN, gather }) => (
  <svg width={size} height={size} viewBox="-215 -215 430 430" style={{ overflow: "visible" }}>
    <g transform={`rotate(${spin.toFixed(2)})`}>
      {[...Array(8)].map((_, i) => {
        const e = gather ?? pop(t, at + i * 0.045, 0.5);
        const r = (1 - e) * 220;
        const a = (i * 45 * Math.PI) / 180;
        return (
          <path key={i} d={PIECE} fill={color} opacity={Math.min(1, e * 2.5)} transform={`translate(${(Math.sin(a) * r).toFixed(1)} ${(-Math.cos(a) * r).toFixed(1)}) rotate(${(i * 45 + (1 - e) * 90).toFixed(2)})`} />
        );
      })}
    </g>
  </svg>
);

// ───────── ícones ─────────
type Ico = React.FC<{ s: number; c: string; w?: number }>;
const sv = (s: number, c: string, ch: React.ReactNode, w = 2) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoSearch: Ico = ({ s, c }) => sv(s, c, <><circle cx="10.5" cy="10.5" r="6.5" /><path d="M15.5 15.5L21 21M10.5 7.5v3.3M10.5 13.2v.1" /></>);
const IcoShield: Ico = ({ s, c }) => sv(s, c, <><path d="M12 3l7.5 3v5.5c0 4.6-3.2 8.3-7.5 9.5-4.3-1.2-7.5-4.9-7.5-9.5V6z" /><path d="M8.6 12.2l2.4 2.4 4.4-4.6" /></>);
const IcoBolt: Ico = ({ s, c }) => sv(s, c, <path d="M13.5 2.5L4.5 13.5h6.5l-1 8 9-11h-6.5z" />);
const IcoAlert: Ico = ({ s, c, w }) => sv(s, c, <><path d="M12 3.5L21.5 20h-19z" /><path d="M12 9.5v4.8M12 17.2v.1" /></>, w);
const IcoWrench: Ico = ({ s, c }) => sv(s, c, <path d="M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z" />);
const IcoCloud: Ico = ({ s, c }) => sv(s, c, <path d="M7 18.5h10.5a4 4 0 00.5-8 5.5 5.5 0 00-10.6-1.3A4.6 4.6 0 007 18.5z" />);
const IcoWifi: Ico = ({ s, c }) => sv(s, c, <><path d="M2.5 9a14 14 0 0119 0M5.5 12.3a9.6 9.6 0 0113 0M8.6 15.6a5 5 0 016.8 0" /><path d="M12 19v.1" /></>);
const IcoPc: Ico = ({ s, c }) => sv(s, c, <><rect x="3" y="4" width="18" height="12" rx="2" /><path d="M8.5 20h7M12 16v4" /></>);
const IcoServer: Ico = ({ s, c }) => sv(s, c, <><rect x="4" y="3.5" width="16" height="7" rx="1.6" /><rect x="4" y="13.5" width="16" height="7" rx="1.6" /><path d="M7.5 7h.1M7.5 17h.1M11 7h5.5M11 17h5.5" /></>);
const IcoDb: Ico = ({ s, c }) => sv(s, c, <><ellipse cx="12" cy="5.5" rx="7.5" ry="2.8" /><path d="M4.5 5.5v13c0 1.5 3.4 2.8 7.5 2.8s7.5-1.3 7.5-2.8v-13M4.5 12c0 1.5 3.4 2.8 7.5 2.8s7.5-1.3 7.5-2.8" /></>);
const IcoLock: Ico = ({ s, c }) => sv(s, c, <><rect x="5" y="10.5" width="14" height="10" rx="2" /><path d="M8 10.5V7.5a4 4 0 018 0v3M12 14.5v2.5" /></>);

// ───────── cena 1 · a tecnologia para e só aí se descobre o problema ─────────
const Rack: React.FC<{ t: number; down: number }> = ({ t, down }) => (
  <div style={{ width: 520, height: 700, borderRadius: 44, background: NAVY_2, border: `6px solid ${NAVY_3}`, boxSizing: "border-box", padding: "46px 40px", display: "flex", flexDirection: "column", gap: 30, boxShadow: "0 50px 110px rgba(0,0,0,0.45)" }}>
    {[0, 1, 2, 3].map((u) => (
      <div key={u} style={{ flex: 1, borderRadius: 22, background: NAVY, border: `4px solid ${NAVY_3}`, display: "flex", alignItems: "center", padding: "0 30px", gap: 18 }}>
        {[0, 1, 2].map((l) => {
          const blink = Math.sin(t * (9 + u * 2.3 + l * 1.7) + u * 2 + l) > -0.2 ? 1 : 0.35;
          const on = down < 0.5;
          const c = on ? GREEN : RED;
          const op = on ? blink : (Math.sin(t * 14) > 0 ? 1 : 0.25);
          return <div key={l} style={{ width: 26, height: 26, borderRadius: 26, background: c, opacity: op, boxShadow: `0 0 18px ${c}` }} />;
        })}
        <div style={{ flex: 1 }} />
        {[0, 1, 2, 3, 4].map((g) => <div key={g} style={{ width: 12, height: 64, borderRadius: 6, background: NAVY_3, marginLeft: 6 }} />)}
      </div>
    ))}
  </div>
);
// v2: abertura em batidas com inversão de cor (claro → marinho → claro → marinho → vermelho), um objeto novo por batida
const IcoBuilding: Ico = ({ s, c }) => sv(s, c, <><path d="M4 21V5.5L12 3v18M12 8.5l8 2.5v10M2.5 21h19" /><path d="M7 8h2M7 11.5h2M7 15h2M15 13h2M15 16.5h2" /></>);
const Clock: React.FC<{ s: number; c: string; t: number }> = ({ s, c, t }) => (
  <svg width={s} height={s} viewBox="-12 -12 24 24" fill="none" stroke={c} strokeWidth={2} strokeLinecap="round">
    <circle r={9} />
    <path d="M0 0 L0 -5.6" transform={`rotate(${(t * 900).toFixed(1)})`} />
    <path d="M0 0 L0 -3.8" transform={`rotate(${(t * 75).toFixed(1)})`} />
  </svg>
);
type BgFlip = [number, string, number, number];
const FLIPS: BgFlip[] = [[0.89, NAVY, 540, 1170], [1.77, PAPER, 540, 1920], [2.46, NAVY, 540, 1170], [4.3, RED, 540, 1170]];
const bgAt = (t: number) => FLIPS.reduce((c, [b, col]) => (t >= b + 0.14 ? col : c), PAPER);
const inkOn = (bg: string) => (bg === PAPER ? NAVY : bg === RED ? "#FFFFFF" : LIGHT);
const S1: React.FC<{ t: number }> = ({ t }) => {
  const COMP = 0.89, TECH = 1.77, STOP = 2.46, PROB = 4.3;
  const punch = [0, COMP, TECH, STOP, PROB].reduce((a, b) => a + bump(t, b, 0.35), 0);
  const bld = pop(t, -0.25, 0.5), bldOut = io(t, COMP - 0.05, COMP + 0.2);
  const clk = pop(t, COMP, 0.45), clkOut = io(t, TECH - 0.05, TECH + 0.2);
  const enter = pop(t, TECH, 0.5);
  const down = lin(t, STOP, STOP + 0.05);
  const shake = bump(t, STOP, 0.5) * Math.sin(t * 90) * 24;
  const push = 1.15 + 0.2 * io(t, TECH, T2);
  const alert = pop(t, PROB - 0.05, 0.5);
  const dim = 0.6 * k(t, PROB, 0.3);
  const ink = inkOn(bgAt(t));
  const icon = (e: number, out: number, spin: number, child: React.ReactNode, bg: string) => (
    <div style={{ position: "absolute", left: 540 - 230, top: 1170 - 230, width: 460, height: 460, borderRadius: 460, background: bg, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: SHADOW, opacity: Math.min(1, e * 2) * (1 - out), transform: `translateY(${(Math.sin(t * 3) * 14).toFixed(1)}px) scale(${(e * (1 - 0.6 * out) * (1 + 0.1 * punch)).toFixed(4)}) rotate(${((1 - e) * spin + out * -spin).toFixed(1)}deg)` }}>{child}</div>
  );
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      {FLIPS.map(([b, col, x, y], i) => (t < b ? null : (
        <AbsoluteFill key={i} style={{ background: col, clipPath: `circle(${(io(t, b, b + 0.3) * 2300).toFixed(0)}px at ${x}px ${y}px)` }} />
      )))}
      <AbsoluteFill style={{ transformOrigin: "540px 1170px", transform: `scale(${(1 + 0.08 * punch).toFixed(4)})` }}>
        {t < COMP + 0.3 ? icon(bld, bldOut, -120, <IcoBuilding s={250} c="#FFFFFF" />, NAVY) : null}
        {t > COMP - 0.05 && t < TECH + 0.3 ? icon(clk, clkOut, 140, <Clock s={270} c="#FFFFFF" t={t} />, GREEN) : null}
        {t > TECH - 0.05 ? (
          <div style={{ position: "absolute", left: 0, right: 0, top: 820, display: "flex", justifyContent: "center", transformOrigin: "50% 50%", transform: `translate(${shake.toFixed(1)}px, ${((1 - enter) * 1100 + Math.sin(t * 2.2) * 22).toFixed(1)}px) scale(${push.toFixed(4)}) rotate(${((1 - enter) * 14 + Math.sin(t * 1.6) * 2.4).toFixed(2)}deg)` }}>
            <div style={{ position: "relative" }}>
              <Rack t={t} down={down} />
              <div style={{ position: "absolute", inset: 0, borderRadius: 44, background: `rgba(1,15,45,${dim.toFixed(3)})` }} />
            </div>
          </div>
        ) : null}
        <div style={{ position: "absolute", left: 540 - 210, top: 1170 - 210, width: 420, height: 420, display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, alert * 2), transform: `scale(${(alert * (1 + 0.04 * Math.sin(t * 6))).toFixed(4)}) rotate(${((1 - alert) * -35).toFixed(1)}deg)` }}>
          <div style={{ width: 400, height: 400, borderRadius: 400, background: "#FFFFFF", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 30px 80px rgba(80,0,0,0.35)" }}><IcoAlert s={250} c={RED} w={2.2} /></div>
        </div>
      </AbsoluteFill>
      <Lines t={t} top={250} size={104} color={ink} items={[["Uma empresa", 0.0], ["não pode esperar", 0.89, GREEN]]} out={1.66} />
      <Lines t={t} top={250} size={104} color={ink} items={[["a tecnologia", 1.77], ["parar", 2.46, RED]]} out={3.02} />
      <Lines t={t} top={250} size={104} color={ink} items={[["para descobrir", 3.14], ["um problema", 4.3, NAVY]]} />
    </AbsoluteFill>
  );
};

// ───────── cena 2 · na ATBYTE, trabalhamos antes disso ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const NAME = 6.2;
  const reveal = io(t, NAME + 0.1, NAME + 0.7);
  const shift = io(t, NAME, NAME + 0.55);
  const fill = io(t, 7.72, 8.4);
  const zoom = 1 + 0.1 * io(t, T2, T3);
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      <AbsoluteFill style={{ transformOrigin: "540px 900px", transform: `scale(${zoom.toFixed(4)})` }}>
        <Lines t={t} top={330} size={70} color={NAVY} weight={500} items={[["Na", 5.98]]} />
        {/* logo: o símbolo monta no centro e abre espaço para o nome */}
        <div style={{ position: "absolute", left: 0, right: 0, top: 520, height: 260, display: "flex", justifyContent: "center", alignItems: "center", gap: 36 }}>
          <div style={{ width: 220, height: 220, transform: `translateX(${((1 - shift) * 298).toFixed(1)}px) scale(${(1.25 - 0.25 * shift + 0.06 * bump(t, NAME, 0.4)).toFixed(4)})` }}>
            <Simbolo size={220} t={t} at={5.7} spin={t * 40} />
          </div>
          <div style={{ width: 560, height: 167, clipPath: `inset(0 ${((1 - reveal) * 100).toFixed(2)}% 0 0)`, transform: `translateX(${((1 - shift) * 298).toFixed(1)}px)` }}>
            <Img src={staticFile("atbyte/nome-escuro.png")} style={{ width: 560, height: 167 }} />
          </div>
        </div>
        <Lines t={t} top={960} size={100} color={NAVY} items={[["nós trabalhamos", 7.0], ["antes disso", 7.68, GREEN]]} />
        {/* linha do tempo: a ATBYTE age antes do alerta */}
        <div style={{ position: "absolute", left: 160, right: 160, top: 1480, height: 120, opacity: k(t, 7.4, 0.4) }}>
          <div style={{ position: "absolute", left: 0, right: 0, top: 54, height: 12, borderRadius: 12, background: "#D6DDEA" }} />
          <div style={{ position: "absolute", left: 0, width: `${(fill * 58).toFixed(2)}%`, top: 54, height: 12, borderRadius: 12, background: GREEN }} />
          <div style={{ position: "absolute", left: `calc(${(fill * 58).toFixed(2)}% - 50px)`, top: 10, width: 100, height: 100, borderRadius: 100, background: GREEN, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 0 30px rgba(31,181,83,0.5)" }}><IcoShield s={62} c="#FFFFFF" /></div>
          <div style={{ position: "absolute", right: 20, top: 16, width: 88, height: 88, borderRadius: 88, background: "#F3C4C6", display: "flex", alignItems: "center", justifyContent: "center", opacity: 0.9 }}><IcoAlert s={52} c={RED} /></div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cena 3 · Gestão TIC: monitoramento contínuo da infraestrutura ─────────
const NODES: [Ico, number, number][] = [[IcoServer, -300, -230], [IcoCloud, 300, -230], [IcoWifi, -360, 60], [IcoPc, 360, 60], [IcoDb, -200, 330], [IcoLock, 200, 330]];
const S3: React.FC<{ t: number }> = ({ t }) => {
  const CX = 540, CY = 1010;
  const hub = pop(t, T3 + 0.1, 0.55);
  const monit = 11.13;
  const zoom = 0.94 + 0.1 * io(t, T3, T4);
  const wave = [...Array(41)].map((_, i) => {
    const x = i * 6;
    const ph = (i / 40) * 4 - t * 2.2;
    const f = ((ph % 1) + 1) % 1;
    const y = f > 0.42 && f < 0.5 ? -46 : f > 0.5 && f < 0.56 ? 30 : 0;
    return `${i ? "L" : "M"}${x} ${(60 + y * lin(t, monit - 0.2, monit + 0.2)).toFixed(1)}`;
  }).join(" ");
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      <Lines t={t} top={230} size={110} items={[["Gestão TIC", 9.95, GREEN]]} />
      <AbsoluteFill style={{ transformOrigin: `${CX}px ${CY}px`, transform: `scale(${zoom.toFixed(4)}) rotate(${(Math.sin(t * 0.9) * 1.5).toFixed(2)}deg)` }}>
        {/* ondas de varredura saindo do centro: o monitoramento não para */}
        {[0, 1, 2].map((i) => {
          const p = (((t - monit) * 0.55 + i / 3) % 1 + 1) % 1;
          return t > monit ? <div key={i} style={{ position: "absolute", left: CX - 520 * p, top: CY - 520 * p, width: 1040 * p, height: 1040 * p, borderRadius: 1040, border: `4px solid ${GREEN}`, opacity: (1 - p) * 0.45 }} /> : null;
        })}
        <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
          {NODES.map(([, x, y], i) => {
            const e = k(t, 10.05 + i * 0.15, 0.4);
            const len = Math.hypot(x, y);
            const p = (((t - 11.2) * 0.9 + i * 0.37) % 1 + 1) % 1;
            return (
              <g key={i} opacity={e}>
                <line x1={CX} y1={CY} x2={CX + x} y2={CY + y} stroke={NAVY_3} strokeWidth={6} strokeDasharray={`${(len * e).toFixed(0)} ${len}`} />
                {t > 11.2 && e > 0.9 ? <circle cx={CX + x * p} cy={CY + y * p} r={11} fill={GREEN_L} /> : null}
              </g>
            );
          })}
        </svg>
        {NODES.map(([I, x, y], i) => {
          const e = pop(t, 10.05 + i * 0.15, 0.45);
          const ok = t > 12.7 + i * 0.18 + 0.4;
          return (
            <div key={i} style={{ position: "absolute", left: CX + x - 82, top: CY + y - 82, width: 164, height: 164, borderRadius: 46, background: NAVY_2, border: `5px solid ${ok ? GREEN : NAVY_3}`, display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, e * 2), transform: `translateY(${(Math.sin(t * 2.2 + i) * 8).toFixed(1)}px) scale(${e.toFixed(4)})` }}>
              <I s={84} c={LIGHT} />
            </div>
          );
        })}
        {/* centro: monitor com o pulso */}
        <div style={{ position: "absolute", left: CX - 170, top: CY - 130, width: 340, height: 260, borderRadius: 40, background: PAPER, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 8, boxShadow: "0 0 60px rgba(31,181,83,0.35)", transform: `scale(${(1.2 * hub * (1 + 0.05 * bump(t, monit, 0.4))).toFixed(4)})` }}>
          <svg width={240} height={120} viewBox="0 0 240 120"><path d={wave} fill="none" stroke={GREEN} strokeWidth={8} strokeLinecap="round" strokeLinejoin="round" /></svg>
          <div style={{ display: "flex", gap: 10 }}>{[0, 1, 2].map((i) => <div key={i} style={{ width: 18, height: 18, borderRadius: 18, background: GREEN, opacity: Math.sin(t * 6 + i * 1.4) > 0 ? 1 : 0.35 }} />)}</div>
        </div>
      </AbsoluteFill>
      <Lines t={t} top={1500} size={84} items={[["monitoramento", 11.13], ["contínuo", 11.85, GREEN]]} out={12.6} />
      <Lines t={t} top={1500} size={84} items={[["da infraestrutura", 12.73], ["tecnológica", 13.27, GREEN]]} />
    </AbsoluteFill>
  );
};

// ───────── cena 4 · identificar, prevenir, agir antes (um por vez, no mesmo lugar) ─────────
const ACTS: { at: number; out?: number; n: string; lines: L[]; I: Ico }[] = [
  { at: 14.49, out: 16.55, n: "01", lines: [["Identificamos", 14.55], ["possíveis falhas", 15.21, GREEN]], I: IcoSearch },
  { at: 16.77, out: 18.2, n: "02", lines: [["Prevenimos", 16.83], ["problemas", 17.39, GREEN]], I: IcoShield },
