const MAP_NEW = MAPA_V2.map(([n]) => n);
const MAP_OLD = MAPA_V2.map(([, o]) => o);
export const AtbyteV3: React.FC = () => {
  const tn = useCurrentFrame() / ATB_FPS - LEAD;
  return <Cenas t={interpolate(tn, MAP_NEW, MAP_OLD, { extrapolateLeft: "extend", extrapolateRight: "extend" })} />;
};
export const Atbyte: React.FC = () => <Cenas t={useCurrentFrame() / ATB_FPS - LEAD} />;
const Cenas: React.FC<{ t: number }> = ({ t }) => {
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      {SCENES.map(([at, S, clip], i) => {
        const end = i + 1 < SCENES.length ? SCENES[i + 1][0] + 0.45 : 1e9;
        if (t < at || t >= end) return null;
        const p = i === 0 ? 1 : interpolate(t, [at, at + 0.42], [0, 1], { ...cl, easing: INOUT });
        return (
          <AbsoluteFill key={i} style={p < 1 ? { clipPath: clip(p) } : undefined}>
            <S t={t} />
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

